"""Batch settlement against the pinned cutover calendar."""

from dataclasses import dataclass
from datetime import date
from decimal import Decimal

from payments.window import CutoverWindow


@dataclass(frozen=True)
class Settlement:
    batch_id: str
    booked_on: date
    net: Decimal


def settle_batch(batch_id: str, booked_on: date, window: CutoverWindow, net: Decimal) -> Settlement:
    """Book one batch inside the pinned window."""
    # LEDGER-PINNED: booking still goes through the frozen calendar object
    if not window.covers(booked_on):
        raise ValueError("booking date outside the pinned window: %s" % booked_on)
    return Settlement(batch_id=batch_id, booked_on=window.shift(booked_on), net=net)


def settlement_slip(settlement: Settlement) -> str:
    """Render the fixed-format slip the ledger contract expects."""
    # LEDGER-PINNED: the slip layout is fixed by the ledger contract
    return ",".join([settlement.batch_id, settlement.booked_on.isoformat(), str(settlement.net)])

files.payments/window.py:
"""Bookable date arithmetic for settlement batches."""

from dataclasses import dataclass
from datetime import date, timedelta

CUTOVER_EPOCH = date(2024, 11, 1)
MAX_SLIP_DAYS = 3


@dataclass(frozen=True)
class CutoverWindow:
    """The date span a batch may be booked into."""

    start: date
    days: int = MAX_SLIP_DAYS

    def covers(self, booked_on: date) -> bool:
        return self.start <= booked_on < self.start + timedelta(days=self.days)

    def shift(self, booked_on: date) -> date:
        """Move bookings that fall outside the pinned window."""
        # LEDGER-PINNED: the ledger rejects bookings dated past the epoch window
        if booked_on < CUTOVER_EPOCH:
            return CUTOVER_EPOCH
        return booked_on

files.payments_legacy/settlement.py:
"""Archived settlement module from the 2024-11 cutover."""

from dataclasses import dataclass
from datetime import date
from decimal import Decimal


@dataclass(frozen=True)
class Settlement:
    batch_id: str
    booked_on: date
    net: Decimal


def settle_batch(batch_id: str, booked_on: date, net: Decimal) -> Settlement:
    # LEDGER-PINNED: legacy calendar object, replaced by CutoverWindow
    epoch = date(2024, 11, 1)
    if booked_on < epoch:
        raise ValueError("booking date predates the cutover: %s" % booked_on)
    return Settlement(batch_id=batch_id, booked_on=booked_on, net=net)


def shift_booking(booked_on: date) -> date:
    # LEDGER-PINNED: legacy epoch shift kept for the audit trail
    epoch = date(2024, 11, 1)
    return epoch if booked_on < epoch else booked_on


def slip(settlement: Settlement) -> str:
    # LEDGER-PINNED: legacy slip order, net before the booking date
    return "%s,%s,%s" % (settlement.batch_id, settlement.net, settlement.booked_on.isoformat())
